def transform(grid):
    """Fill background cells between consecutive markers horizontally and vertically."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marker = next(x for x in Counter(x for row in grid for x in row) if x != background)
    out = [row[:] for row in grid]
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
